// Local document extraction and cited passage retrieval. No remote model call.
function documentTerms(value){const stop=new Set(['how','do','does','the','is','it','a','an','of','to','and','can','what','this','are','i']);return [...new Set((value.toLowerCase().match(/[a-z0-9]{2,}/g)||[]).filter(t=>!stop.has(t)))]}
function findDocumentPassages(text,question){const terms=documentTerms(question);const parts=text.split(/\n\s*\n/).flatMap(p=>p.length>700?(p.match(/[\s\S]{1,500}/g)||[]):[p]).map(s=>s.trim()).filter(Boolean);return parts.map((p,i)=>({text:p,index:i+1,score:terms.reduce((sum,t)=>sum+(p.toLowerCase().includes(t)?t.length:0),0)})).filter(p=>p.score>0).sort((a,b)=>b.score-a.score).slice(0,2)}
function documentChatRuntime(data){
 const log=document.querySelector('#chat-log'),form=document.querySelector('#chat-form'),input=document.querySelector('#chat-question');
 function append(text,kind){const el=document.createElement('div');el.className='message '+kind;el.textContent=text;log.append(el);while(log.children.length>22)log.firstElementChild.remove();log.scrollTop=log.scrollHeight}
 function ask(question){question=question.trim().slice(0,240);if(!question)return;append(question,'user');const hits=findDocumentPassages(data.text,question);if(!hits.length){append('No matching passage found. Try keywords from the source or open the full text. This local search only quotes the document.','assistant');return}append('Related source passages:\n\n'+hits.map(h=>h.text+'\n〔'+data.name+' · Passage '+h.index+'〕').join('\n\n'),'assistant')}
 function send(){ask(input.value);input.value=''}form.onsubmit=e=>{e.preventDefault();send()};form.querySelector('button').onclick=e=>{e.preventDefault();send()};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();send()}};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));document.querySelector('#source-text').textContent=data.text;document.querySelector('#source-name').textContent=data.name;append('Ask a question about this document. Answers include matching passages and source references.','assistant');
}
function documentSliceHtml(doc){const json=JSON.stringify(doc).replace(/</g,'\\u003c');const suggestions=doc.sample?['How do I adjust brightness?','Does it work wirelessly?','How long is the warranty?']:['What features are available?','How do I use it?','What precautions should I take?'];return `<!doctype html><html lang="en"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}html,body{height:100%;margin:0}body{font:14px system-ui;color:#243a43;background:#f1f6f7;display:flex;flex-direction:column}.top{padding:14px 16px 8px;border-bottom:1px solid #dce7e8}.top small{font-size:10px;color:#758c90;letter-spacing:1px}.top h2{font-size:18px;margin:4px 0}.top p{font-size:11px;margin:3px 0;color:#819498}#chat-log{flex:1;min-height:50px;overflow:auto;padding:12px 15px;display:flex;flex-direction:column;gap:9px}.message{padding:10px 12px;background:white;border-radius:10px;white-space:pre-wrap;line-height:1.7;font-size:12px;overflow-wrap:anywhere}.user{align-self:flex-end;background:#d5e9d8;max-width:90%}.assistant{align-self:flex-start}.quick{display:flex;gap:5px;padding:5px 12px;overflow-x:auto;flex-shrink:0}button{font:inherit;cursor:pointer}.quick button{white-space:nowrap;font-size:11px;border:1px solid #d7e2df;background:white;border-radius:20px;padding:7px 9px}form{display:flex;gap:6px;padding:8px 12px 10px}input{min-width:0;flex:1;padding:10px;border:1px solid #cddbd8;border-radius:7px;font:inherit;font-size:12px}form button{background:#2b4f49;color:white;border:0;padding:9px 13px;border-radius:7px}details{padding:0 14px 8px;font-size:10px;max-height:110px;overflow:auto}summary{cursor:pointer;color:#718580}pre{white-space:pre-wrap;font:12px system-ui}button:focus-visible,input:focus-visible{outline:2px solid #698c68;outline-offset:2px}html{color-scheme:dark}body{background:#111a15;color:#e5eee7}.top{border-color:#334438}.top small,.top p,summary{color:#a1b7a8}.message{background:#1c2a21}.user{background:#2c4022}.quick button{background:#1c2a21;color:#dbe8dc;border-color:#3d5142}input{background:#0a100c;color:#e5eee7;border-color:#3d5142}input::placeholder{color:#9bad9f}form button{background:#c6ff3a;color:#0b1007}button:focus-visible,input:focus-visible{outline-color:#c6ff3a}</style><body><div class="top"><small>DOCUMENT → CONVERSATIONAL SLICE</small><h2>${escapeHtml(doc.title||doc.name)}</h2><p>Local source search · No AI inference · Offline</p></div><div id="chat-log" role="log" aria-live="polite" aria-label="Document questions and answers"></div><div class="quick">${suggestions.map(q=>`<button type="button" data-question="${escapeHtml(q)}">${escapeHtml(q)}</button>`).join('')}</div><form id="chat-form"><input id="chat-question" aria-label="Ask the document" placeholder="Ask about this manual…" required maxlength="240"><button>Send</button></form><details><summary>View source · <span id="source-name"></span></summary><pre id="source-text"></pre></details><script>${documentTerms.toString()};${findDocumentPassages.toString()};(${documentChatRuntime.toString()})(${json});<\/script></body></html>`}
const manualText=`Luma One Desk Lamp Manual (fictional demo product)

Features: Luma One is a reading lamp with three brightness levels and three color temperatures. The lamp head tilts and the base has touch controls.

Brightness and color: Tap power to switch the lamp on or off. Tap brightness to cycle through low, medium, and high. Hold brightness for two seconds to switch between warm, natural, and cool light.

Power and wireless use: Connect the included USB-C cable to a 5V / 2A adapter. There is no battery. The lamp must stay plugged in and cannot work wirelessly.

Timer: Hold power and brightness for three seconds. Two flashes confirm a 30-minute auto-off timer. Repeat to cancel.

Care: Switch off and unplug before wiping with a soft, dry cloth. Do not rinse or use alcohol or abrasive cleaners. For dry indoor use only.

Troubleshooting: If the lamp does not light, check the USB-C connection and power adapter. Try another compatible 5V / 2A supply. Do not open the base.

Warranty: One year of limited coverage from purchase, with proof of purchase. Accidental damage, water damage, and unauthorized disassembly are excluded.

In the box: One desk lamp, one USB-C cable, and one quick-start guide. Power adapter not included.

Demo notice: This product, its specifications, and its warranty are fictional and only demonstrate an interactive document experience.`;
const manualDoc={name:'Luma-One-Manual.txt',title:'A manual you can ask questions',text:manualText,sample:true};
const manualWork={id:'manual-chat',cat:'Knowledge',title:'Ask the manual.',desc:'How bright? Does it work wirelessly? Ask a manual and explore its source passages.',author:'Luma Studio',time:'Interactive document · Demo',likes:84,plays:'362',bg:'#e1eeee',assetType:'html',asset:documentSliceHtml(manualDoc),template:'quiz',contentType:'interactive'};
works.unshift(manualWork);render();
if(location.hash==='#work=manual-chat')openWork('manual-chat');
